        window.onload = function () {
            const regionSelect = document.getElementById('regionSelect');
            for (const region in uzbRegionsData) {
                const opt = document.createElement('option');
                opt.value = region;
                opt.textContent = region;
                opt.className = "bg-slate-900 text-white";
                regionSelect.appendChild(opt);
            }
        };

        function updateDistricts() {
            const selectedRegion = document.getElementById('regionSelect').value;
            const districtSelect = document.getElementById('districtSelect');
            districtSelect.innerHTML = '<option value="" disabled selected class="bg-slate-900 text-slate-400">Tuman / Shaharni tanlang</option>';
            if (selectedRegion && uzbRegionsData[selectedRegion]) {
                districtSelect.disabled = false;
                uzbRegionsData[selectedRegion].forEach(function (district) {
                    const opt = document.createElement('option');
                    opt.value = district;
                    opt.textContent = district;
                    opt.className = "bg-slate-900 text-white";
                    districtSelect.appendChild(opt);
                });
            } else {
                districtSelect.disabled = true;
            }
        }

        document.getElementById('courseSelect').addEventListener('change', function () {
            const info = courseImages[this.value];
            const box = document.getElementById('coursePreview');
            if (info) {
                document.getElementById('courseImg').src = info.src;
                document.getElementById('courseImg').alt = this.value;
                document.getElementById('courseCaption').textContent = info.caption;
                box.classList.remove('hidden');
            } else {
                box.classList.add('hidden');
            }
        });

        function handleFormSubmit(event) {
            event.preventDefault();
            const fullName = document.getElementById('fullName').value.trim();
            const phone = document.getElementById('phoneNumber').value.trim();
            const region = document.getElementById('regionSelect').value;
            const district = document.getElementById('districtSelect').value;
            const course = document.getElementById('courseSelect').value;
            const shift = document.querySelector('input[name="shift"]:checked').value;

            window.applicationData = { fullName, phone, region, district, course, shift };

            document.getElementById('sumName').textContent = fullName;
            document.getElementById('sumPhone').textContent = phone;
            document.getElementById('sumLocation').textContent = region + ", " + district;
            document.getElementById('sumCourse').textContent = course;
            document.getElementById('sumShift').textContent = shift + " smena";

            document.getElementById('registrationFormCard').classList.add('hidden');
            const success = document.getElementById('successCard');
            success.classList.remove('hidden');
            requestAnimationFrame(function () {
                success.classList.remove('scale-95', 'opacity-0');
                success.classList.add('scale-100', 'opacity-100');
            });
        }

        function closeTelegramApp() {
            if (tg && tg.sendData && window.applicationData) {
                tg.sendData(JSON.stringify(window.applicationData));
            } else if (tg && tg.close) {
                tg.close();
            }
        }

        function resetForm() {
            document.getElementById('enrollmentForm').reset();
            document.getElementById('phoneNumber').value = "+998 ";
            document.getElementById('districtSelect').innerHTML = '<option value="" disabled selected class="bg-slate-900 text-slate-400">Avval viloyatni tanlang</option>';
            document.getElementById('districtSelect').disabled = true;
            document.getElementById('coursePreview').classList.add('hidden');
            window.applicationData = null;

            const success = document.getElementById('successCard');
            success.classList.add('hidden', 'scale-95', 'opacity-0');
            success.classList.remove('scale-100', 'opacity-100');
            document.getElementById('registrationFormCard').classList.remove('hidden');
        }